preset.pixel_eqs_eel:
thresh = above(bass_att,thresh)*2+(1-above(bass_att,thresh))*((thresh-1.3)*0.96+1.3);
dx_r = equal(thresh,2)*0.015*sin(5*time)+(1-equal(thresh,2))*dx_r;
dy_r = equal(thresh,2)*0.015*sin(6*time)+(1-equal(thresh,2))*dy_r;
dx = dx + above(x,0.5)*x*0.005;
dx = dx - below(x,0.5)*(1-x)*0.005;
dy = dy + above(y,0.5)*y*0.005;
dy = dy + below(y,0.5)*(1-y)*0.005;
zoom = zoom - 100*((1-rad)*((1.5*rad)*0.005 + 0.004*sin(0.5*bass_att)));

rot = rot + (cos(bass_att*treb_att)/(1-treb)+0.5*time)*0.0005;
zoomexp = 0.8 + 1+sin(treb_att);
